		korean = "^C656565FF00000000오븐과 스토브를 절묘하게 결합한 이 가전제품은 주방 작업을 한결 쾌적하게 만들어줍니다."
	},
	item10101871 = {
		schinese = "流动的盛宴",
		tchinese = "",
		english = "流动的盛宴",
		japanese = "流れる盛宴",
		korean = "흐르는 향연"
	},
	item10101871desc = {
		schinese = "^C656565FF00000000这是一座非常古老的城市，这里什么都不简单，甚至贫穷、意外所得的钱财、月光、是与非，以及那在月光下睡在你身边的人的呼吸，都不简单。",
		tchinese = "",
		english = "^C656565FF00000000这是一座非常古老的城市，这里什么都不简单，甚至贫穷、意外所得的钱财、月光、是与非，以及那在月光下睡在你身边的人的呼吸，都不简单。",
		japanese = "^C656565FF00000000こちらは歴史感のある町、何もかも簡単ではない。貧乏、意外な富、月光、是と非及び月光に照らされる隣で寝ている人の呼吸さえ、簡単ではない。",
		korean = "^C656565FF00000000이곳은 오래된 도시로 쉬운 일이 하나도 없고 일정하지 않은 수입으로 가난과 불의가 판을 치며 달밤 아래 잠자리조차도 쉬운 법이 없습니다."
	},
	item10023471 = {
		schinese = "银饰雕花靠椅",
		tchinese = "",
		english = "银饰雕花靠椅",
		japanese = "銀飾椅子",
		korean = "은빛 모자이크 의자"
	},
	item10023471desc = {
		schinese = "^C656565FF00000000美观、优雅的象征，价格不菲，据说，在某个靠椅的背上还刻着一个人的名字：Ernest Miller——后面似乎看不太清了。",
		tchinese = "",
		english = "^C656565FF00000000美观、优雅的象征，价格不菲，据说，在某个靠椅的背上还刻着一个人的名字：Ernest Miller——后面似乎看不太清了。",
		japanese = "^C656565FF00000000華麗、優雅の象徴、値段はかなり高い。話によると椅子の後ろに一人の名前が刻まれている:Ernest Miller――後の文字ははっきり見えない。",
		korean = "^C656565FF00000000우아하고 고상하며 값비싼 의자로 뒤에 이름이 새겨져 있습니다.：Ernest Miller——등 뒤를 조심해야겠군요."
	},
	item10023571 = {
		schinese = "银饰圆桌",
		tchinese = "",
		english = "银饰圆桌",
		japanese = "銀飾円卓",
		korean = "은빛 탁자"
	},
	item10023571desc = {
		schinese = "^C656565FF00000000丁香咖啡馆为了吸引顾客而采购的新桌子，大气、美观。这里很适合在充满阳光的午后点一杯咖啡，开始一天的创作。",
		tchinese = "",
		english = "^C656565FF00000000丁香咖啡馆为了吸引顾客而采购的新桌子，大气、美观。这里很适合在充满阳光的午后点一杯咖啡，开始一天的创作。",
		japanese = "^C656565FF00000000クローブカフェが新しく購入した円卓、結構おしゃれな感じがする。日差しの溢れる午後でカフェを味わいながら、一日の創作を始めるのが最高だ！",
		korean = "^C656565FF00000000클로버 까페에서 고상하고 아름다운 분위기를 연출하기 위해 주문했습니다. 햇살 가득한 오후, 한 잔의 커피와 함께 야근까지 힘냅시다."
	},
	item10023671 = {
		schinese = "今日特价菜",
