		japanese = "本日のおすすめ",
		korean = "투데이 스페셜"
	},
	item10023671desc = {
		schinese = "^C656565FF00000000丁香咖啡馆每天的特价菜展览牌，昨天是毕加索通心面，今天似乎是海明威胡椒牛排……",
		tchinese = "",
		english = "^C656565FF00000000丁香咖啡馆每天的特价菜展览牌，昨天是毕加索通心面，今天似乎是海明威胡椒牛排……",
		japanese = "^C656565FF00000000クローブカフェの日替わりおすすめ看板、昨日はピカソパスタ、今日はヘミングウェイ胡椒ステーキらしい……",
		korean = "^C656565FF00000000클로버 까페의 일일 특가 요리입니다. 어제는 피카소 파스타였고 오늘은 헤밍웨이 후추 스테이크라는군요……"
