	item10023771desc = {
		schinese = "^C656565FF00000000海瑟薇书店供路人休息时翻阅的书架和座位，没有什么装饰，许多作家都会在这里停留，也因此这里一直被视为这座城市最富有的地方。",
		tchinese = "",
		english = "^C656565FF00000000海瑟薇书店供路人休息时翻阅的书架和座位，没有什么装饰，许多作家都会在这里停留，也因此这里一直被视为这座城市最富有的地方。",
		japanese = "^C656565FF00000000通りかかる人の休憩のためにハサウェイ書店が設置した本棚と椅子。特に装飾されていないが、多くの作家が利用している。だから、ここがこの町で一番富裕な場所だと皆は認識している。",
		korean = "^C656565FF00000000해서웨이 서점은 길거리에서 사람들이 편히 쉬며 책을 읽고, 또한 장식을 배제한 캐주얼함으로 많은 작가들이 머뭅니다. 또한 가장 부유한 지역이기도 하죠."
	},
