		schinese = "在我军的迅猛攻势下，深海军势在坷垃美群岛的作战节节败退。作战期间，我方派特种部队潜入敌方要塞，窃取代号“幽谷百合”机密文件，并派遣驱逐舰护送特种部队安全撤离。",
