		english = "在我军的迅猛攻势下，深海军势在坷垃美群岛的作战节节败退。作战期间，我方派特种部队潜入敌方要塞，窃取代号“幽谷百合”机密文件，并派遣雷童子护送特种部队安全撤离。",
		japanese = "わが軍の攻勢により、深海軍が敗退し続けている。今回の作戦は、敵軍要塞に潜入し、機密文書「コード：谷間のゆり」を盗み出す特殊部隊の撤退を駆逐艦で援護することである。",
		korean = "우리 함대의 공세로 심해함대가 각 군도에서 패퇴하고 있다. 전투가 벌어지는 동안 우리는 특수부대를 적의 요새로 보내 코드명 “백합의 골짜기”라는 기밀문서를 입수했다. 이번 작전은 적 요새에 구축함 한 척을 잠입시켜서 특수부대의 철수를 엄호하는 것이다."
