	tutorial_1_0 = {
		schinese = "^C656565FF00000000指挥官，您刚刚到任，本想向您介绍一下港区内的功能设施，但我们刚接到报告显示在^C1C8BE5FF00000000[母港附近海域]^C656565FF00000000发现了小股的敌人。",
		tchinese = "",
		english = "^C656565FF00000000指挥官，您刚刚到任，本想向您介绍一下基地内的功能设施，但我们刚接到报告显示在^C1C8BE5FF00000000[基地附近海域]^C656565FF00000000发现了小股的敌人。",
		japanese = "^C656565FF00000000提督、着任したばかりで、港区の施設を紹介したいところですが、^C1C8BE5FF00000000[母港付近水域]^C656565FF00000000に敵を発見したという報告を受けました。",
		korean = "^C656565FF00000000반갑습니다, 제독. 저는 아이라라고 합니다. 절차상 우선 제독님이 지휘하실 모항을 소개시켜드리는 것이 맞겠습니다만, 방금 ^C1C8BE5FF00000000[모항 인근 해역]^C656565FF00000000에서 소규모 적 함대가 활동 중이라는 보고가 들어왔습니다."
	},
	tutorial_1_1 = {
		schinese = "^C656565FF00000000为了安全起见我们需要先携带舰船进行迎战，点击^C1C8BE5FF00000000[出征]^C656565FF00000000即可进入出征界面。",
		tchinese = "",
		english = "^C656565FF00000000为了安全起见我们需要先携带战斗员进行迎战，点击^C1C8BE5FF00000000[出征]^C656565FF00000000即可进入出征界面。",
		japanese = "^C656565FF00000000安全のために艦船が編成されている艦隊で迎撃する必要があります。^C1C8BE5FF00000000[出撃]^C656565FF00000000をタップし、出撃ページに入ります。",
		korean = "^C656565FF00000000안전을 위해 우선 이들을 격퇴하도록 하죠. ^C1C8BE5FF00000000[출격] ^C656565FF00000000버튼을 터치하여 출격 준비 화면을 엽시다."
	},
	tutorial_1_2 = {
		schinese = "^C656565FF00000000请选择出击地图，进行出击准备。",
		tchinese = "",
		english = "^C656565FF00000000请选择出击地图，进行出击准备。",
		japanese = "^C656565FF00000000出撃の海域を選んで、出撃準備を行ってください",
		korean = "^C656565FF00000000출격을 하기 위해서는 우선 출격 해역을 결정해야합니다. 해역 지도를 터치해주세요."
	},
	tutorial_1_3 = {
		schinese = "^C656565FF00000000在出征准备界面可以确认本次出战的舰队，查看舰船的耐久和补给情况。",
		tchinese = "",
		english = "^C656565FF00000000在出征准备界面可以确认本次出战的战队，查看战斗员的耐久和补给情况。",
		japanese = "^C656565FF00000000出撃準備の画面で今回出撃の艦隊、耐久値と補給状況を確認できます。",
		korean = "^C656565FF00000000출격 준비 화면에서 제독님은 출동할 함대 및 함선소녀들의 보급 및 내구도를 확인할 수 있습니다."
	},
	tutorial_1_4 = {
		schinese = "^C656565FF00000000准备好以后就出击吧，点击^C1C8BE5FF00000000[开始出征]^C656565FF00000000。",
		tchinese = "",
		english = "^C656565FF00000000准备好以后就出击吧，点击^C1C8BE5FF00000000[开始出征]^C656565FF00000000。",
		japanese = "^C8B806EFF00000000準備が出来たら出撃しましょう、^C668F18FF00000000「出撃」^C8B806EFF00000000をタップしてください",
		korean = "^C656565FF00000000준비되시는대로 ^C1C8BE5FF00000000[출격개시] ^C656565FF00000000버튼을 터치해주세요."
	},
	tutorial_1_5 = {
		schinese = "^C656565FF00000000恭喜指挥官！我们取得了初次战斗的胜利，在战斗结算画面您可以确认获得的经验以及新加入的舰船。",
		tchinese = "",
		english = "^C656565FF00000000恭喜指挥官！我们取得了初次战斗的胜利，在战斗结算画面您可以确认获得的经验以及新加入的战斗员。",
		japanese = "^C656565FF00000000提督おめでとうございます！初めての勝利を勝ち取りました。戦闘完了画面では獲得した経験値と新しく入ってきた艦船を確認できます。",
		korean = "^C656565FF00000000축하합니다, 제독님! 착임하시자마자 첫 승리를 거두셨군요. 전투 결과 화면에서는 함선소녀가 획득한 경험치 확인, 그리고 새로운 함선소녀 합류 보고를 받으실 수 있습니다."
	},
	tutorial_1_6 = {
		schinese = "^C656565FF00000000虽然追击可以扩大战果，但在刚才的战斗中我们的舰船受损了，现在先返回港口进行修整吧！之后再一鼓作气干掉敌人。",
		tchinese = "",
		english = "^C656565FF00000000虽然追击可以扩大战果，但在刚才的战斗中我们的战斗员受损了，现在先返回基地进行修整吧！之后再一鼓作气干掉敌人。",
		japanese = "^C656565FF00000000追撃では戦果を挙げることができますが、さっきの戦闘では艦船が損傷しており、今はとりあえず母港に帰還し修復しましょう！後で一気に敵を叩き潰しましょう。",
		korean = "^C656565FF00000000계속 적 함대를 수색하여 전과를 극대화할 수 있겠지만, 방금 전 전투에서 아군 함선이 손상을 입었습니다. 우선 모항으로 돌아가서 수리를 하죠. 그 후 다시 돌아와서 이 해역의 심해함대를 싹 쓸어버립시다."
	},
	tutorial_2_0 = {
		schinese = "^C656565FF00000000通过刚才的战斗，我们完成了一个战斗任务，现在可以领取奖励了，详情请到任务面板中进行确认吧。",
		tchinese = "",
		english = "^C656565FF00000000通过刚才的战斗，我们完成了一个战斗任务，现在可以领取奖励了，详情请到任务面板中进行确认吧。",
		japanese = "^C656565FF00000000今回の出撃によりクエストを完了したため、報酬を受け取れます。詳細は任務画面で確認してください",
		korean = "^C656565FF00000000방금 전 전투로 임무를 하나 완수했습니다. 각 임무들은 다양한 보상을 제공합니다. 어서 임무 패널에서 확인합시다."
	},
	tutorial_2_1 = {
		schinese = "^C656565FF00000000点击^C1C8BE5FF00000000[领取奖励]^C656565FF00000000即可领取任务奖励。",
		tchinese = "",
		english = "^C656565FF00000000点击^C1C8BE5FF00000000[领取奖励]^C656565FF00000000即可领取任务奖励。",
		japanese = "^C1C8BE5FF00000000「報酬受領」^C656565FF00000000をタップし、任務報酬を受け取ることができます。",
		korean = "^C1C8BE5FF00000000[보상 획득]^C656565FF00000000을 터치하여 임무 보상을 수령하세요."
	},
	tutorial_2_2 = {
		schinese = "^C656565FF00000000点击^C1C8BE5FF00000000[确认]^C656565FF00000000，收取奖励。",
		tchinese = "",
		english = "^C656565FF00000000点击^C1C8BE5FF00000000[确认]^C656565FF00000000，收取奖励。",
		japanese = "^C1C8BE5FF00000000「決定」^C656565FF00000000をタップし、任務報酬を受け取ってください。",
		korean = "^C1C8BE5FF00000000[확인]^C656565FF00000000을 터치해주세요."
	},
	tutorial_2_3 = {
		schinese = "^C656565FF00000000如果接到新的任务就第一时间把它完成吧，现在我们返回港口，对舰队进行修整。",
		tchinese = "",
		english = "^C656565FF00000000如果接到新的任务就第一时间把它完成吧，现在我们返回基地，对战队进行修整。",
		japanese = "^C656565FF00000000新しい任務を受けたら、早く完成しましょう。今は母港に戻り、艦隊を整備します。",
		korean = "^C656565FF00000000하나의 임무를 완료하면 연계되는 새로운 임무를 수취하는 경우가 있습니다. 그러니 가능한 빠르게 임무를 수행하시고 완료 보고를 해주세요. 자, 이제 항구에 가서 함선를 수리하도록 하죠."
	},
	tutorial_3_0 = {
		schinese = "^C656565FF00000000指挥官，在刚才的战斗中有舰船受损，而且舰队携带的燃料等资源不足。让受损的舰船持续作战是很危险的事情，携带缺乏补给的舰船出击也会很吃力。",
		tchinese = "",
		english = "^C656565FF00000000指挥官，在刚才的战斗中有战斗员受损，而且战队携带的燃料等资源不足。让受损的战斗员持续作战是很危险的事情，携带缺乏补给的战斗员出击也会很吃力。",
		japanese = "^C656565FF00000000提督、さっきの戦闘では艦隊が損傷を受け、燃料などの資源も不足しています。損傷がある艦船で戦い続けることがとても危険なことです。補給が不足している艦船が出撃してもきついです。",
		korean = "^C656565FF00000000제독님, 방금 전 전투에서 아군 함선소녀는 피해를 입었고, 연료와 탄약 사용으로 보급을 필요로 하고 있습니다. 피해를 입은 함선소녀를 전투에 투입하는 것은 극도로 위험한 행위입니다. 또한 보급 부족은 함선소녀의 전투 효율 저하를 야기합니다."
	},
	tutorial_3_1 = {
		schinese = "^C656565FF00000000现在先对受损的舰船进行修理，修理可以在港区或船坞中进行。",
		tchinese = "",
		english = "^C656565FF00000000现在先对受损的战斗员进行疗养，疗养可以在基地或基地中进行。",
		japanese = "^C656565FF00000000損傷を受けた艦船を修復します。港区や泊地で行います。",
		korean = "^C656565FF00000000우선 수리를 해보도록 하죠. 도크, 그리고 항구 구역의 욕탕에서 실시할 수 있습니다."
	},
	tutorial_3_2 = {
		schinese = "^C656565FF00000000点击右上角的^C1C8BE5FF00000000[修理舰船]^C656565FF00000000即可进入修理界面。",
		tchinese = "",
		english = "^C656565FF00000000点击右上角的^C1C8BE5FF00000000[疗养战斗员]^C656565FF00000000即可进入疗养界面。",
		japanese = "^C656565FF00000000右上の^C1C8BE5FF00000000「艦船修復」^C656565FF00000000をタップし、修復画面に入ります。",
		korean = "^C656565FF00000000우측 상단에 있는 ^C1C8BE5FF00000000[함선 수리]^C656565FF00000000를 터치해주세요."
	},
	tutorial_3_3 = {
		schinese = "^C656565FF00000000点击^C1C8BE5FF00000000[选择舰船]^C656565FF00000000即可选择要修理的舰娘。",
		tchinese = "",
		english = "^C656565FF00000000点击^C1C8BE5FF00000000[选择战斗员]^C656565FF00000000即可选择要疗养的战斗员娘。",
		japanese = "^C1C8BE5FF00000000「艦船選択」^C656565FF00000000をタップし、^C656565FF00000000修復する艦船を選べます。",
		korean = "^C1C8BE5FF00000000[함선 선택]^C656565FF00000000을 터치하여 수리가 필요한 함선을 선택하세요."
	},
	tutorial_3_4 = {
		schinese = "^C656565FF00000000点击舰船即可对其进行修理，要注意确认修理消耗的资材。",
		tchinese = "",
		english = "^C656565FF00000000点击战斗员即可对其进行疗养，要注意确认疗养消耗的资材。",
		japanese = "^C656565FF00000000艦隊内の損傷した艦船を選択して、修復を始めてください。修復に必要な資源も確認してください。",
		korean = "^C656565FF00000000함선소녀를 터치해주세요. 소요되는 자원을 유의해주세요."
