	tutorial_6_0 = {
		schinese = "^C656565FF00000000获得新舰娘的途径除了出征以外还有^C1C8BE5FF00000000[建造]^C656565FF00000000，通过建造新的舰娘来快速壮大舰队的实力也是一个不错的选择。",
		tchinese = "",
		english = "^C656565FF00000000获得新战斗员娘的途径除了出征以外还有^C1C8BE5FF00000000[训练]^C656565FF00000000，通过训练新的战斗员娘来快速壮大战队的实力也是一个不错的选择。",
		japanese = "^C656565FF00000000出撃以外の新しい艦船を入手する手段は^C1C8BE5FF00000000「建造」^C656565FF00000000です。建造により迅速に艦隊の実力を拡大することもよい選択です。",
		korean = "^C656565FF00000000해역에서의 전투 외에 ^C1C8BE5FF00000000[건조] ^C656565FF00000000를 실시하는 것도 새로운 함선소녀를 쉽게 모집할 수 있는 좋은 방법입니다."
	},
	tutorial_6_1 = {
		schinese = "^C656565FF00000000事不宜迟，现在就赶快试一下吧，点击^C1C8BE5FF00000000[建造]^C656565FF00000000。",
		tchinese = "",
		english = "^C656565FF00000000事不宜迟，现在就赶快试一下吧，点击^C1C8BE5FF00000000[训练]^C656565FF00000000。",
		japanese = "^C656565FF00000000では早速試しましょう。^C1C8BE5FF00000000[建造]^C656565FF00000000をタップしてください",
		korean = "^C656565FF00000000백 번 말하는 것보단 직접 해보는 편이 좋겠죠. ^C1C8BE5FF00000000[건조]^C656565FF00000000를 터치해주세요."
	},
	tutorial_6_2 = {
		schinese = "^C656565FF00000000指挥官在达到10级以前是无法建造出非常稀有的舰船的。",
		tchinese = "",
		english = "^C656565FF00000000指挥官在达到10级以前是无法训练出非常稀有的战斗员的。",
		japanese = "^C656565FF00000000提督レベル10以下の場合、レア艦を建造できません。",
		korean = "^C656565FF00000000제독님의 레벨이 10이 되기 전까지는 희귀한 함선이 건조되지 않음을 유의해주세요."
	},
	tutorial_6_3 = {
		schinese = "^C656565FF00000000点击^C1C8BE5FF00000000[建造]^C656565FF00000000，即可进入建造资源选择界面。",
		tchinese = "",
		english = "^C656565FF00000000点击^C1C8BE5FF00000000[训练]^C656565FF00000000，即可进入训练资源选择界面。",
		japanese = "^C1C8BE5FF00000000[建造]^C656565FF00000000をタップし、建造資源選択画面に入ります",
		korean = "^C1C8BE5FF00000000[건조]^C656565FF00000000를 눌러 건조 계획 화면을 열 수 있습니다. 여기서 건조에 투입할 자원의 양을 결정합니다."
	},
	tutorial_6_4 = {
		schinese = " ",
		tchinese = "",
		english = " ",
		japanese = "^C656565FF00000000「建造」には「燃料、弾薬、鋼材、ボーキサイト」４種類の資源、及び「艦船設計図」が必要です。",
		korean = "^C656565FF00000000새로운 함선의 의장을 제작하기 위해 필요한 자원은 연료와 탄약, 강재, 그리고 알루미늄이 며 여기에 건조도면이 한 장 필요합니다. "
	},
	tutorial_6_5 = {
		schinese = "^C656565FF00000000依据资源投入的比例，会产生不同的建造结果，在右下角的^C1C8BE5FF00000000[建造日志]^C656565FF00000000中可以看到其他提督使用过的资源配方和建造结果，现在请点击^C1C8BE5FF00000000[建造]^C656565FF00000000按钮。",
		tchinese = "",
		english = "^C656565FF00000000依据资源投入的比例，会产生不同的训练结果，在右下角的^C1C8BE5FF00000000[训练日志]^C656565FF00000000中可以看到其他指挥官使用过的资源配方和训练结果，现在请点击^C1C8BE5FF00000000[训练]^C656565FF00000000按钮。",
		japanese = "^C656565FF00000000使う資源の量、比例により、違う建造結果が出てきます。右下の^C1C8BE5FF00000000「建造記録」^C656565FF00000000にはほかの提督の建造レシピと結果を見れます。^C1C8BE5FF00000000「建造」^C656565FF00000000ボタンをタップしてください",
		korean = "^C656565FF00000000어떤 자원을 얼마나 투입하냐에 따라 건조 결과가 달라질 수 있습니다. 우측 하단 ^C1C8BE5FF00000000[건조 기록]^C656565FF00000000을 통해 타 제독들의 처절한 기록들을 참고하는 것도 좋은 방법이죠. ^C1C8BE5FF00000000[건조]^C656565FF00000000를 터치해주세요."
	},
	tutorial_6_6 = {
		schinese = "^C656565FF00000000舰船的建造需要时间，由于现在急需扩充舰队战力，使用^C1C8BE5FF00000000[快速建造]^C656565FF00000000吧，通过快速建造可以立刻完成建造，获得新的舰娘。",
		tchinese = "",
		english = "^C656565FF00000000战斗员的训练需要时间，由于现在急需扩充战队战力，使用^C1C8BE5FF00000000[快速训练]^C656565FF00000000吧，通过快速训练可以立刻完成训练，获得新的战斗员娘。",
		japanese = "^C656565FF00000000建造が完了まで時間がかかります。現在はすぐに戦力を拡大する必要があるため、^C1C8BE5FF00000000[高速建造]^C656565FF00000000を使いましょう。高速建造によりすぐに建造を終わらせ、新しい艦船を獲得できます。",
		korean = "^C656565FF00000000건조에는 시간이 필요합니다. 급할 때는 ^C1C8BE5FF00000000[고속건조]^C656565FF00000000 기능을 써서 건조 시간을 완전히 무시하고 바로 새로운 함선소녀를 충원할 수 있습니다."
	},
