		schinese = "^C656565FF00000000现在可以把刚刚获得的新舰娘编入到出击舰队里，点击^C1C8BE5FF00000000[船坞]^C656565FF00000000。",
		tchinese = "",
		english = "^C656565FF00000000现在可以把刚刚获得的新战斗员娘编入到出击战队里，点击^C1C8BE5FF00000000[基地]^C656565FF00000000。",
		japanese = "^C656565FF00000000先ほど獲得した艦船を出撃艦隊に編成できます。^C1C8BE5FF00000000[泊地]^C656565FF00000000をタップしてください。",
		korean = "^C656565FF00000000방금 들어온 새 함선소녀를 함대에 편성해보죠. ^C1C8BE5FF00000000[도크]^C656565FF00000000를 터치해주세요."
	},
	tutorial_8_1 = {
		schinese = "^C656565FF00000000在编队界面，点击舰队中空着的位置就可以选择要上阵的舰船。",
		tchinese = "",
		english = "^C656565FF00000000在编队界面，点击战队中空着的位置就可以选择要上阵的战斗员。",
		japanese = "^C656565FF00000000編成画面で、開いている位置をタップすると、出撃する艦船を選択できます。",
		korean = "^C656565FF00000000편성 패널에서 함대의 빈 공간을 터치해주세요. 그리고 함선소녀를 터치하여 함대에 편성해주세요."
	},
	tutorial_8_2 = {
		schinese = "^C656565FF00000000每只舰队中最多可以上阵6艘舰船，不同类型的舰船具有各自的优势，编成合适的舰队可以更好的对付不同种类的敌人。",
		tchinese = "",
		english = "^C656565FF00000000每只战队中最多可以上阵6艘战斗员，不同类型的战斗员具有各自的优势，编成合适的战队可以更好的对付不同种类的敌人。",
		japanese = "^C656565FF00000000一つの艦隊には最大6隻の艦船を入れられます。艦種によって特性や強みが異なります。敵の特性に対応できる艦隊の編成をお勧めします。",
		korean = "^C656565FF00000000각 함대는 최대 6명의 함선소녀를 편성할 수 있습니다. 각 함종마다 저마다의 장단점과 역할을 가지고 있습니다. 작전을 진행할 해역에 등장하는 심해함대를 효과적으로 상대할 수 있게끔 면밀히 검토하여 편성해주세요. "
	},
	tutorial_8_3 = {
		schinese = "^C656565FF00000000点击舰船即可将其加入上阵舰队中，现在就把刚获得的新舰船加入第一舰队吧。",
		tchinese = "",
		english = "^C656565FF00000000点击战斗员即可将其加入上阵战队中，现在就把刚获得的新战斗员加入第一战队吧。",
		japanese = "^C656565FF00000000艦船をタップすると、編成に入れられます。獲得した新しい艦船を第一艦隊に入れましょう。",
		korean = "^C656565FF00000000함선소녀를 터치하여 제 1함대에 편성해줍니다."
	},
	tutorial_8_4 = {
		schinese = "^C656565FF00000000编队完成，现在可以返回港口。",
		tchinese = "",
		english = "^C656565FF00000000编队完成，现在可以返回基地。",
		japanese = "^C656565FF00000000編成完了！母港に戻りましょう。",
		korean = "^C656565FF00000000편성이 완료되었습니다. 이제 항구로 돌아가죠."
	},
	tutorial_9_0 = {
		schinese = "^C656565FF00000000舰队已经修整完毕，现在可以去清扫港口周围的敌人了，点击^C1C8BE5FF00000000[出征]^C656565FF00000000。",
		tchinese = "",
		english = "^C656565FF00000000战队已经修整完毕，现在可以去清扫基地周围的敌人了，点击^C1C8BE5FF00000000[出征]^C656565FF00000000。",
		japanese = "^C656565FF00000000艦隊整備完了、母港付近の敵を掃討しましょう。^C1C8BE5FF00000000[出撃]^C656565FF00000000をタップしてください。",
		korean = "^C656565FF00000000새 함대도 편성되었고 정비도 마쳤습니다. 앞서 말씀드렸다시피 이 주변에서 얼쩡대는 심해함대를 싹 쓸어낼 시간이 온 거죠. ^C1C8BE5FF00000000[출격]^C656565FF00000000을 터치해주세요."
	},
	tutorial_9_1 = {
		schinese = "^C656565FF00000000选择^C1C8BE5FF00000000[母港附近海域]^C656565FF00000000地图，进行出击准备。",
		tchinese = "",
		english = "^C656565FF00000000选择^C1C8BE5FF00000000[基地附近海域]^C656565FF00000000地图，进行出击准备。",
		japanese = "^C1C8BE5FF00000000[母港付近水域]^C656565FF00000000を選択し、出撃の準備を始めてください。",
		korean = "^C1C8BE5FF00000000[모항 인근 해역]^C656565FF00000000 지도를 터치해주세요. 그리고 전투를 준비합시다."
	},
	tutorial_9_2 = {
		schinese = "^C656565FF00000000现在可以看到我们的舰队状态是完好的，点击^C1C8BE5FF00000000[开始出征]^C656565FF00000000，进行出击，我会在之后的战斗中辅助您。",
		tchinese = "",
		english = "^C656565FF00000000现在可以看到我们的战队状态是完好的，点击^C1C8BE5FF00000000[开始出征]^C656565FF00000000，进行出击，我会在之后的战斗中辅助您。",
		japanese = "^C656565FF00000000艦隊は完全な状態です。^C1C8BE5FF00000000[出撃]^C656565FF00000000をタップし、出撃してください。あとの戦闘ではサポートいたします。",
		korean = "^C656565FF00000000현재 제독님의 함대는 아주 좋은 상태입니다. 당장 ^C1C8BE5FF00000000[출격개시]^C656565FF00000000를 눌러 전장으로 향합시다. 이어질 전투에서 전투 대형에 대해 설명드리겠습니다."
	},
	tutorial_10_0 = {
		schinese = "^C656565FF00000000在战斗开始前如果索敌成功，会显示敌方舰队的信息，在战斗前可以依据索敌的情况选择出战的阵型。",
		tchinese = "",
		english = "^C656565FF00000000在战斗开始前如果索敌成功，会显示敌方战队的信息，在战斗前可以依据索敌的情况选择出战的阵型。",
		japanese = "^C656565FF00000000索敵が成功すると、敵方の艦隊情報が表示されます。索敵の結果により戦闘の陣形を選択を選択しましょう。",
		korean = "^C656565FF00000000사전정찰을 통한 적 발견, 즉 색적에 성공하면 적 함대의 진용을 확인할 수 있습니다. 이를 바탕으로 적 함대의 구성 및 진형을 파악할 수 있습니다."
	},
	tutorial_10_1 = {
		schinese = "^C656565FF00000000采用不同阵型具有不同的战斗效果，具体说明在阵型选择处列出，现在可以点击^C1C8BE5FF00000000[开始战斗]^C656565FF00000000。",
		tchinese = "",
		english = "^C656565FF00000000采用不同阵型具有不同的战斗效果，具体说明在阵型选择处列出，现在可以点击^C1C8BE5FF00000000[开始战斗]^C656565FF00000000。",
		japanese = "^C656565FF00000000陣形がそれぞれの効果があります。選択する時確認してください。^C1C8BE5FF00000000[戦闘開始]^C656565FF00000000をタップしてください",
		korean = "^C656565FF00000000함대를 구성하는 함선소녀가 4명 이상이면 진형을 결정할 수 있습니다. 각 진형 효과는 선택 화면에서 확인하실 수 있습니다. ^C1C8BE5FF00000000[전투개시]^C656565FF00000000를 터치해주세요."
	},
