	secretary_description = {
		schinese = "1、秘书舰组最多可设置6位秘书舰，相同图鉴的舰船也可以设置。\n2、秘书舰组第一位秘书舰会常驻提督府并获得好感度，其她秘书舰不会获得。\n3、勾选列表随机后，每次回到港区主界面都会在秘书舰列表里随机一位秘书舰显示。\n4、当港区主界面秘书舰不为live2D状态时，左右滑动可以对秘书舰进行切换。\n5、重置列表会将秘书舰组变更为第一舰队旗舰。",
		tchinese = "",
		english = "1、助理组最多可设置6位助理，相同图鉴的战斗员也可以设置。\n2、助理组第一位助理会常驻指挥官府并获得好感度，其她助理不会获得。\n3、勾选列表随机后，每次回到基地主界面都会在助理列表里随机一位助理显示。\n4、当基地主界面助理不为特殊动画状态时，左右滑动可以对助理进行切换。\n5、重置列表会将助理组变更为第一战队领队。",
		japanese = "1、秘書艦編成に6隻の秘書艦を設置できます。図鑑が同じとなる艦も設置できます。\n2、秘書艦編成の1隻目の秘書艦は提督室に配置され、好感度も上昇します。ほかの秘書艦は好感度を獲得できません。\n3、「ランダム」を選択したら、メイン画面に戻るたびに秘書艦リストからランダムで秘書艦が表示されます。\n4、live2Dでない状態では、左右スライドして秘書艦を切り替えます。\n5、リストリセットしたら、秘書艦編成は第一艦隊の旗艦に変わります。",
